INSERT INTO public.chef_kaggle_steps (recipe_id,position,instruction) VALUES
('Caramelized_Onions_Roasted_Red_Peppers_Quiche',26,'Combine the remaining ricotta with garlic. Evenly spread it at the bottom of the quiche (see video).'),
