CREATE TABLE public.chef_curated_ingredients (recipe_id text REFERENCES public.chef_kaggle_recipes(id), ingredient_key text, label_es text NOT NULL, source_step integer NOT NULL, evidence_text text NOT NULL, optional integer CHECK(optional IN (0,1)), quantity numeric, unit text, PRIMARY KEY(recipe_id,ingredient_key), FOREIGN KEY(recipe_id,source_step) REFERENCES public.chef_kaggle_steps(recipe_id,position));
